using System;
using System.IO;
using System.Collections.Generic;

public static class InputSources {
 static string[] labels;
 public static string Label(int? source,bool detail){if(!source.HasValue)return "Source loading";if(labels==null){labels=new string[179];foreach(string line in File.ReadAllLines(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"input-patch.csv"))){string[] cells=line.Split(',');labels[int.Parse(cells[0])]=cells[1];}}int n=source.Value;if(n<0||n>=179)return "Unknown source";if(n==0)return "Unpatched";if(n<=24)return detail?"Onboard analog input "+n:"AD "+n;if(n<=120){int slot=(n-25)/16+1,port=(n-25)%16+1;return detail?"Slot "+slot+" · Input "+port:"S"+slot+"-"+port;}string code=labels[n];if(!detail)return code;if(code.StartsWith("FX")){string[] bits=code.Substring(2).Split('-');return "Internal effect "+bits[0]+" · Output "+bits[1];}if(code.StartsWith("2TD"))return "2-track digital "+code[3]+" · "+code[4];if(code.StartsWith("2TA"))return "2-track analog "+code[3]+" · "+code[4];if(code.StartsWith("BUS"))return "Internal bus "+code.Substring(3);if(code.StartsWith("AUX"))return "Internal aux "+code.Substring(3);return code;}
 public static void Test(){if(Label(1,true)!="Onboard analog input 1"||Label(25,true)!="Slot 1 · Input 1"||Label(120,true)!="Slot 6 · Input 16"||Label(0,true)!="Unpatched")throw new Exception("Source port mapping failed");for(int i=0;i<179;i++)if(string.IsNullOrEmpty(Label(i,true)))throw new Exception("Missing source mapping");}
 public static void Probe(){using(var connection=FeatureTests.Open())using(var log=new StreamWriter(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"input-sources.txt"))){log.AutoFlush=true;for(int bank=0;bank<4;bank++){connection.SetMixerView(bank,-1);var end=DateTime.UtcNow.AddSeconds(6);bool ready;do{System.Threading.Thread.Sleep(20);if(connection.Error!=null)throw new Exception(connection.Error);ready=true;foreach(int id in FaderConnection.ViewIds(bank))if(!connection.Channel(id).Source.HasValue)ready=false;}while(!ready&&DateTime.UtcNow<end);foreach(int id in FaderConnection.ViewIds(bank)){var s=connection.Channel(id);if(!s.Source.HasValue)throw new Exception("Input source missing for "+(id+1));log.WriteLine("Input "+(id+1)+": "+Label(s.Source,true));}}log.WriteLine("PASS: all 96 input patch sources read.");}}
}
